Sass Variables & Maps:
// Custom Bootstrap (custom.scss)
// 1. Override variables BEFORE importing Bootstrap
$primary: #6f42c1;
$success: #20c997;
$font-family-sans-serif: 'Inter', sans-serif;
$border-radius: 0.5rem;

// 2. Add a custom color
$custom-colors: (
  'custom-color': #ff6b6b
);
$theme-colors: map-merge($theme-colors, $custom-colors);

// 3. Custom spacer
$spacers: map-merge($spacers, (
  6: $spacer * 4,
  7: $spacer * 5
));

// 4. Import Bootstrap
@import 'bootstrap/scss/bootstrap';

CSS Custom Properties:
:root {
  --bs-primary: #6f42c1;
  --bs-body-bg: #f8f9fa;
  --bs-body-color: #212529;
  --bs-border-radius: 0.5rem;
}

/* Override per component instance */
.custom-card {
  --bs-card-bg: #2d2d2d;
  --bs-card-color: #fff;
  --bs-card-border-color: #444;
}

/* Dark theme via CSS vars */
[data-bs-theme="dark"] {
  --bs-body-bg: #212529;
  --bs-body-color: #dee2e6;
  --bs-border-color: #495057;
}

/* JavaScript: document.documentElement.setAttribute('data-bs-theme', 'dark') */

Components & Theming:
// _custom.scss — component toggles
$enable-rounded: true;
$enable-shadows: true;
$enable-gradients: false;
$enable-transitions: true;
$enable-reduced-motion: true;
$enable-smooth-scroll: true;
$enable-grid-classes: true;
$enable-cssgrid: false;
$enable-button-pointers: true;
$enable-validation-icons: true;
$enable-negative-margins: true;

// Example: custom button theme
$btn-padding-y-lg: 1rem;
$btn-padding-x-lg: 2rem;
$btn-border-radius-lg: 50rem;  // pill buttons

@import 'bootstrap/scss/bootstrap';

Modal & Offcanvas:
// JavaScript API
const myModal = new bootstrap.Modal(
  document.getElementById('myModal'),
  { backdrop: 'static', keyboard: false }
);
myModal.show();

// Events
document.getElementById('myModal').addEventListener('shown.bs.modal', function () {
  console.log('Modal shown');
});

// Offcanvas
const offcanvas = new bootstrap.Offcanvas(
  document.getElementById('myOffcanvas')
);
offcanvas.show();

// Static backdrop modal
<button class="btn btn-primary"
  data-bs-toggle="modal" data-bs-target="#staticBackdrop"
  data-bs-backdrop="static" data-bs-keyboard="false">
  Launch static modal
</button>
